package com.bechir.keyboard;
import android.inputmethodservice.InputMethodService;import android.content.*;import android.graphics.Color;import android.graphics.Typeface;import android.graphics.drawable.GradientDrawable;import android.view.*;import android.view.inputmethod.*;import android.widget.*;import android.os.Handler;import android.os.Looper;import android.animation.*;
public class BechirIME extends InputMethodService {
 private final Handler handler=new Handler(Looper.getMainLooper());private Runnable repeatDelete;private LinearLayout body;private int lang=0;private boolean shift=false;private boolean symbols=false;
 private final String[][][] letters={{{"ض","ص","ث","ق","ف","غ","ع","ه","خ","ح","ج","د","ذ"},{"ش","س","ي","ب","ل","ا","ت","ن","م","ك","ط"},{"ئ","ء","ؤ","ر","لا","ى","ة","و","ز","ظ"}},{{"a","z","e","r","t","y","u","i","o","p"},{"q","s","d","f","g","h","j","k","l","m"},{"w","x","c","v","b","n","é","è","à"}},{{"q","w","e","r","t","y","u","i","o","p"},{"a","s","d","f","g","h","j","k","l"},{"z","x","c","v","b","n","m"}}};
 public View onCreateInputView(){body=new LinearLayout(this);body.setOrientation(1);body.setPadding(4,9,4,14);body.setBackgroundColor(0xff100d1c);render();return body;}
 private GradientDrawable bg(int color){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(13*getResources().getDisplayMetrics().density);return d;}
 private void key(LinearLayout row,String s,int weight,Runnable action,boolean special){
 TextView t=new TextView(this);t.setText(s);t.setTextColor(Color.WHITE);t.setTextSize(s.length()>4?13:19);t.setTypeface(null,Typeface.BOLD);t.setGravity(Gravity.CENTER);
 t.setBackground(bg(special?0xff4a2e86:0xff2a243c));
 LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,(int)(49*getResources().getDisplayMetrics().density),weight);p.setMargins(2,3,2,3);row.addView(t,p);
 t.setOnTouchListener((v,event)->{if(event.getAction()==MotionEvent.ACTION_DOWN){t.animate().scaleX(0.91f).scaleY(0.91f).setDuration(70).start();t.setBackground(bg(0xff8653d8));}else if(event.getAction()==MotionEvent.ACTION_UP||event.getAction()==MotionEvent.ACTION_CANCEL){t.animate().scaleX(1f).scaleY(1f).setDuration(120).start();t.setBackground(bg(special?0xff4a2e86:0xff2a243c));}return false;});
 t.setOnClickListener(v->action.run());
 if(s.equals("⌫")){t.setOnLongClickListener(v->{repeatDelete=new Runnable(){public void run(){deleteOne();handler.postDelayed(this,85);}};handler.post(repeatDelete);return true;});t.setOnTouchListener((v,e)->{if(e.getAction()==MotionEvent.ACTION_DOWN){t.setBackground(bg(0xff8653d8));t.animate().scaleX(.91f).scaleY(.91f).setDuration(70).start();}if(e.getAction()==MotionEvent.ACTION_UP||e.getAction()==MotionEvent.ACTION_CANCEL){if(repeatDelete!=null){handler.removeCallbacks(repeatDelete);repeatDelete=null;}t.setBackground(bg(0xff4a2e86));t.animate().scaleX(1).scaleY(1).setDuration(100).start();}return false;});}
 }
 private void deleteOne(){InputConnection c=getCurrentInputConnection();if(c!=null){CharSequence selected=c.getSelectedText(0);if(selected!=null&&selected.length()>0)c.commitText("",1);else c.deleteSurroundingTextInCodePoints(1,0);}}
 private void send(String s){InputConnection c=getCurrentInputConnection();if(c!=null)c.commitText(s,1);}
 private void render(){body.removeAllViews();LinearLayout toolbar=new LinearLayout(this);toolbar.setGravity(Gravity.CENTER_VERTICAL);body.addView(toolbar);key(toolbar,"BECHIR",2,()->{},true);key(toolbar,new String[]{"عربي","FR","EN"}[lang],1,()->{lang=(lang+1)%3;symbols=false;render();},true);key(toolbar,"123",1,()->{symbols=!symbols;render();},true);
 if(symbols){String[][] sym={{"1","2","3","4","5","6","7","8","9","0"},{"@","#","$","%","&","-","+","(",")","/"},{"*","\" ",":",";","!","?","'","،",".","_"}};for(String[] rr:sym)row(rr);}
 else for(String[] rr:letters[lang])row(rr);
 LinearLayout last=new LinearLayout(this);body.addView(last);key(last,"⇧",1,()->{shift=!shift;render();},true);key(last,"،",1,()->send(lang==0?"،":","),false);key(last,"مسافة",4,()->send(" "),false);key(last,".",1,()->send("."),false);key(last,"⌫",1,()->deleteOne(),true);key(last,"↵",1,()->{InputConnection c=getCurrentInputConnection();if(c!=null)c.sendKeyEvent(new KeyEvent(KeyEvent.ACTION_DOWN,KeyEvent.KEYCODE_ENTER));if(c!=null)c.sendKeyEvent(new KeyEvent(KeyEvent.ACTION_UP,KeyEvent.KEYCODE_ENTER));},true);}
 private void showVariants(TextView anchor,String[] variants){PopupMenu menu=new PopupMenu(this,anchor);for(String v:variants)menu.getMenu().add(v);menu.setOnMenuItemClickListener(item->{send(item.getTitle().toString());return true;});menu.show();}
 private void row(String[] rr){LinearLayout row=new LinearLayout(this);body.addView(row);for(String s:rr){final String k=shift?s.toUpperCase():s;key(row,k,1,()->send(k),false);TextView t=(TextView)row.getChildAt(row.getChildCount()-1);if(lang==0&&!symbols){String[] variants=null;if(s.equals("ا"))variants=new String[]{"أ","إ","آ","ٱ"};else if(s.equals("و"))variants=new String[]{"ؤ"};else if(s.equals("ي"))variants=new String[]{"ئ","ى"};else if(s.equals("ه"))variants=new String[]{"ة"};else if(s.equals("ء"))variants=new String[]{"ء","أ","إ","ؤ","ئ"};if(variants!=null){final String[] options=variants;t.setOnLongClickListener(v->{showVariants(t,options);return true;});}}}}
}